export type BlogCluster =
  | "informational"
  | "commercial"
  | "comparison"
  | "technical"
  | "regional"
  | "case";

export type BlogIntent =
  | "informational"
  | "commercial"
  | "comparison"
  | "howto"
  | "case";

export interface BlogSection {
  title: string;
  paragraphs?: string[];
  /** Маркированный список (рендерится после абзацев). */
  bullets?: string[];
  /** Таблица внутри секции (рендерится после абзацев). */
  table?: {
    headers: string[];
    rows: string[][];
    caption?: string;
  };
}

export interface BlogArticle {
  slug: string;
  h1: string;
  description: string;
  primaryKeyword: string;
  secondaryKeywords: string[];
  cluster: BlogCluster;
  intent: BlogIntent;
  regional: boolean;
  volume: string;
  intro: string;
  sections: BlogSection[];
  relatedSlugs: string[];
  /** Дата последнего содержательного обновления статьи — уходит в sitemap lastmod. */
  updatedAt?: string;
}

function article(
  slug: string,
  h1: string,
  description: string,
  primaryKeyword: string,
  secondaryKeywords: string[],
  cluster: BlogCluster,
  intent: BlogIntent,
  regional: boolean,
  volume: string,
  intro: string,
  sections: BlogSection[],
  relatedSlugs: string[],
  updatedAt?: string
): BlogArticle {
  return {
    slug,
    h1,
    description,
    primaryKeyword,
    secondaryKeywords,
    cluster,
    intent,
    regional,
    volume,
    intro,
    sections,
    relatedSlugs,
    updatedAt,
  };
}

