          "Норма затухания на 1310 нм — до 0,35 дБ/км, на 1550 — до 0,22 дБ/км. Стыки считаются по факту трассы: сшивка катушек, вводы в муфты. Опытный сварщик держит 0,03–0,05 дБ на стык, но в бюджет закладывайте паспортные 0,08–0,1 дБ — так расчёт переживёт смену бригады.",
