          "Здесь же живёт сплиттер 1:8 или 1:16 — его вносимые потери считаются отдельной строкой: около 10,5 дБ для 1:8 и 13,5–14 дБ для 1:16 (паспортные значения конкретного сплиттера точнее средних). Распределительный участок короткий — десятки-сотни метров, поэтому затуханием волокна на нём часто пренебрегают, но коннекторы и сплиттер — нет.",
