          "Важно: у поставляемых ELIZON марок — 242 ± 5 мкм, то есть стандартное индустриальное значение. Любое волокно [G.657.A2](/optovolokno/g657/g657a2) сваривается с [G.652.D](/optovolokno/g652/g652d) и A1 без адаптации: диаметры сердцевины и оболочки у всех одинаковы, изгибостойкость достигается профилем показателя преломления, а не размерами.",
