export function getBlogArticleBySlug(slug: string): BlogArticle | undefined {
  return blogArticles.find((a) => a.slug === slug);
}

export function getAllBlogSlugs(): string[] {
  return blogArticles.map((a) => a.slug);
}

export function getBlogArticlesByCluster(cluster: BlogCluster): BlogArticle[] {
  return blogArticles.filter((a) => a.cluster === cluster);
}

export const blogClusterLabels: Record<BlogCluster, string> = {
  informational: "Информационные",
  commercial: "Коммерческие",
  comparison: "Сравнительные",
  technical: "Технические",
  regional: "Региональные",
  case: "Кейсы и практика",
};